// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }

    function testFuzz_property(uint256 seed) public {
        // version() is pure and takes no args; the fuzz parameter exercises the call repeatedly.
        string memory v = c.version();
        assertTrue(
            keccak256(bytes(v)) == keccak256(bytes("1.0.0")),
            "version string must be the reference 1.0.0"
        );
    }
}
